import { useState } from "react";
import axios from "axios";

const SendOTP = () => {
    const [email, setEmail] = useState("");
    const [message, setMessage] = useState("");

    const handleSendOTP = async () => {
        try {
            const res = await axios.post("http://localhost:5000/api/candidats/send-otp", { email });
            setMessage(res.data.message);
        } catch (error) {
            setMessage(error.response?.data?.error || "Erreur lors de l'envoi du code.");
        }
    };

    return (
        <div className="send-otp-container">
            <h2>Recevoir votre code de sécurité</h2>
            <input
                type="email"
                placeholder="Entrez votre email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
            />
            <button onClick={handleSendOTP}>Envoyer le code</button>
            {message && <p>{message}</p>}
        </div>
    );
};

export default SendOTP;
